@export
def base(n: int, k: int):
    x = 0
    for i in range(k * 50):
        x += i
    return x

@export
def eq(n: int, k: int):
    l = list(range(n))
    m = list(range(n))
    c = 0
    for i in range(k):
        if l == m:
            c += 1
    return c

@export
def lt(n: int, k: int):
    l = list(range(n))
    m = list(range(n))
    c = 0
    for i in range(k):
        if l < m:
            c += 1
    return c

@export
def contains(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        if -1 in l:
            c += 1
    return c

@export
def index(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += l.index(n - 1)
    return c

@export
def count(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += l.count(-1)
    return c

@export
def dictbuild(n: int, k: int):
    d = {}
    for i in range(n):
        d[str(i)] = i
    return len(d)

@export
def dictlookup(n: int, k: int):
    d = {}
    for i in range(n):
        d[str(i)] = i
    c = 0
    last = str(n - 1)
    for i in range(k):
        c += d[last]
    return c

@export
def dicteq(n: int, k: int):
    d = {}
    e = {}
    for i in range(n):
        d[i] = i
        e[n - 1 - i] = n - 1 - i
    c = 0
    for i in range(k):
        if d == e:
            c += 1
    return c

@export
def concat(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(l + l)
    return c

@export
def slice(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(l[:])
    return c

@export
def listcopy(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(list(l))
    return c

@export
def tuplecopy(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(tuple(l))
    return c

@export
def strlist(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(str(l))
    return c

@export
def reverse(n: int, k: int):
    l = list(range(n))
    for i in range(k):
        l.reverse()
    return len(l)

@export
def insert0(n: int, k: int):
    l = list(range(n))
    for i in range(k):
        l.insert(0, 1)
    return len(l)

@export
def pop0(n: int, k: int):
    l = list(range(n + k))
    for i in range(k):
        l.pop(0)
    return len(l)

@export
def mul(n: int, k: int):
    l = [1]
    c = 0
    for i in range(k):
        c += len(l * n)
    return c

@export
def sortedl(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(sorted(l))
    return c

@export
def summ(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += sum(l) + max(l) + min(l)
    return c

@export
def joins(n: int, k: int):
    l = ['ab'] * n
    c = 0
    for i in range(k):
        c += len(''.join(l))
    return c

@export
def dictcopy(n: int, k: int):
    d = {str(i): i for i in range(n)}
    c = 0
    for i in range(k):
        c += len(dict(d))
    return c

@export
def length(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(l)
    return c

@export
def setops(n: int, k: int):
    a = set(range(n))
    b = set(range(n))
    c = 0
    for i in range(k):
        c += len(a | b)
    return c

@export
def extend(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        m = []
        m.extend(l)
        c += len(m)
    return c

@export
def strindex(n: int, k: int):
    s = 'a' * n
    c = 0
    for i in range(k):
        c += len(s[n - 1])
    return c

@export
def keys(n: int, k: int):
    d = {str(i): i for i in range(n)}
    c = 0
    for i in range(k):
        c += len(list(d.keys()))
    return c

@export
def anyall(n: int, k: int):
    l = [True] * n
    c = 0
    for i in range(k):
        if all(l):
            c += 1
    return c

@export
def zipl(n: int, k: int):
    l = list(range(n))
    c = 0
    for i in range(k):
        c += len(list(zip(l, l)))
    return c
